mapper.update:
update car
set mileage = #{updateParam.mileage},
price   = #{updateParam.price}
where id = #{id}

mapper.select:
select id, car_number, manufacturer, model_name, model_year, mileage, price, status
from car
where id = #{id}

select id, car_number, manufacturer, model_name, model_year, mileage, price, status
from car
where car_number = #{carNumber}

select id, car_number, manufacturer, model_name, model_year, mileage, price, status
from car


        and model_name like concat('%', #{modelName}, '%')


        and price <= #{maxPrice}


        and status = #{status}


order by id desc
